CHANGELOG = '## [0.263.0] - a hall the id names and says nothing more of is a hallway\n\n**The walker\'s walk of cold run 9383** (the factory\'s `docs/findings/walk_2026-10-23_deli/`, finding 3; roadmap 300),\nof deli_a03\'s stair landing `upper_hall`: "layout of these tables doesn\'t seem to have a rhyme or reason". The\nlanding took the `hall` kind by its id\'s token -- the row for galleries, chapels and courtrooms -- and was given a\nservice counter, waiting benches, vending, a cigarette machine and a dining table with its chairs. 45 of the 64 rooms\nthat row furnished are connectors, nearly all hallways and stair landings: `upper_hall` (24 of them), `back_hall`,\n`rear_hall`, `mezz_hall`. The role cannot tell them apart -- `connector` is 896 rooms, kitchens, offices and bars\namong them -- the id\'s words can.\n\n### Changed\n- **`_ROOM_KINDS`**: the `hall` row keeps the gathering words (gallery, exhibit, chapel, assembly, courtroom,\n  viewing, artifact) and loses "hall" itself; a last row, `hallway`, takes "hall" when no other kind\'s word does, so\n  `assembly_hall` stays a hall and `cellar_hall` and `under_hall` stay basements. 40 rooms in 38 library specs move\n  from `hall` to `hallway` and no room changes kind otherwise.\n- **The `hallway` recipe**: benches, a file cabinet, a bin and vending against the walls, at most six pieces, nothing\n  on the floor. Movement first; its floor share sits under the walker\'s 12-25 % band on purpose, and is reported.\n- Below grade a hallway takes no basement clutter, as a corridor does not.\n\n### The library, refurnished and sheltered\n- **40 rooms in 38 specs moved and no other** (the factory\'s `patches/dc_hallway/rooms_moved.out.txt`), none holding\n  an objective or loot marker. Furnish\'s pieces 8,510 -> 8,154; the moved rooms\' floor share fell from 2.3-12.8 % to\n  0.9-7.3 %, the shelter pieces counted. The 32 cigarette machines that stood in them go (118 -> 86 in the\n  library); none moved elsewhere.\n- **The shelter pass** (`migrate_shelter.py`) stood a kiosk in courthouse_a02\'s and survival_demo\'s `upper_hall`, whose\n  only shelter had been the gallery set, and a tall crate stack in gas_station_a02\'s `back_hall`, which had none.\n  Every combat hallway is sheltered but stop_n_go\'s 27 m2 `back_hall`, under the seeder\'s 30 m2 floor\n  (`_SEED_MIN_AREA`) and unsheltered before this too.\n- **The route census** (the factory\'s `docs/findings/furnish_route_cost/route_cost.py`, both libraries in one\n  session): routes over the guide\'s 10 % detour 26 pairs in 25 rooms -> 23 in 22; narrowed from two abreast to single\n  file 151 -> 142; closed to a body 0 -> 0, to the bake 5 -> 5.\n\n### Tests\n- `test_furnish.py`: `upper_hall` and `back_hall` are hallways, `assembly_hall` and `chapel` halls -- failing on\n  0.262.0 on the first.\n- `test_club_fixtures.py`: its hall example was `upper_hall`, now `exhibit_hall`, and `upper_hall` stands no cigarette\n  machine; the library\'s 118 machines are 86.\n- `test_marker_room_routes.py` mirrors furnish\'s below-grade rule, `hallway` in it.\n\n'
OLD_VERSION, NEW_VERSION = 'Deli Counter 0.262.0', 'Deli Counter 0.263.0'


def _sha(b):
    return hashlib.sha256(b).hexdigest()[:16]


def _read(name):
    """The file's LF text and whether it is CRLF on disk; refuses mixed endings and a file that is not the pinned one."""
    raw = (REPO / name).read_bytes()
    crlf, lf = raw.count(b"\r\n"), raw.count(b"\n")
    if crlf not in (0, lf):
        raise SystemExit("REFUSED: deli_counter/%s has mixed line endings (%d CRLF of %d); nothing written"
                         % (name, crlf, lf))
    text = raw.decode("utf-8").replace("\r\n", "\n")
    if _sha(text.encode("utf-8")) != PINS[name]:
        raise SystemExit("REFUSED: deli_counter/%s is %s, not the %s this patch was written against; nothing "
                         "written" % (name, _sha(text.encode("utf-8")), PINS[name]))
    return text, crlf > 0


def main(argv):
    # every file worked out and checked before any is written
    out = {}
    for name, edits in EDITS.items():
        text, crlf = _read(name)
        for what, old, new in edits:
            if text.count(old) != 1:
                raise SystemExit("REFUSED: deli_counter/%s: the anchor at %s is there %d times; nothing written"
                                 % (name, what, text.count(old)))
            text = text.replace(old, new)
        out[name] = text.replace("\n", "\r\n") if crlf else text
    # a refurnished spec is carried whole, the file it replaces pinned like any other
    for name, text in REPLACED.items():
        _old, crlf = _read(name)
        out[name] = text.replace("\n", "\r\n") if crlf else text
    for name in NEW_FILES:
        if (REPO / name).exists():
            raise SystemExit("REFUSED: deli_counter/%s exists already; nothing written" % name)
    v = REPO / "VERSION"
    if v.read_bytes().decode("utf-8") != OLD_VERSION:
        raise SystemExit("REFUSED: VERSION reads %r, not %s; nothing written" % (v.read_text(), OLD_VERSION))
    cl = REPO / "CHANGELOG.md"
    craw = cl.read_bytes()
    if b"\r\n" in craw or not craw.startswith(b"## [" + OLD_VERSION.split()[-1].encode() + b"]"):
        raise SystemExit("REFUSED: CHANGELOG.md is not LF opening on %s; nothing written" % OLD_VERSION)
    for name, text in out.items():
        (REPO / name).write_bytes(text.encode("utf-8"))
    for name, text in NEW_FILES.items():
        (REPO / name).write_bytes(text.encode("utf-8"))
    v.write_bytes(NEW_VERSION.encode("utf-8"))
    cl.write_bytes(CHANGELOG.encode("utf-8") + craw)
    print("%s applied: %d files edited, %d written, VERSION, CHANGELOG. Now, in deli_counter/: build.py --all, "
          "suite" % (NEW_VERSION, len(out), len(NEW_FILES)))
    return 0


if __name__ == "__main__":
    sys.exit(main(sys.argv[1:]))
